    pub(crate) fn oc1493_fake_read_action(c: &mut Cpu) {
        // The first action read answers at +0xc, the second (returning to
        // 0x16c4ac) at +0x10.
        let slot = if c.g[RA][0] as u32 == 0x0016_c4ac {
            0x10
        } else {
            0xc
        };
        oc1493_answer(
            c,
            OC1493_RT_GATE,
            OC1493_RT_MAGIC,
            &OC1493_PREV_READ_ACTION,
            ee::s02::f_0016c518__generated,
            0x0016_c518,
            slot,
        );
    }

