    pub(crate) fn oc1494_tail_setup(c: &mut Cpu, seed: u32, salt: u64) {
        let mut r = machine(c, seed, salt, 0);
        c.g[T0][0] = sx(DATA + 0x100);
        c.g[A1][0] = 0;
        c.f[1] = r.next_u32();
    }

